"""Offline synchronized six-group overview and individual model comparison."""
import json
from models import headings

def make_replay(out,runs,agents,metrics):
    data={key:dict(time=r['time'].round(3).tolist(),position=r['position'].round(4).tolist(),
                   half_box=agents[key].half_box.tolist(),radius=agents[key].radius.tolist(),
                   heading=headings(agents[key]).round(10).tolist(),metric=metrics[key]) for key,r in runs.items()}
    html=r'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Week 06 · 六组人车圆周交会</title><style>
*{box-sizing:border-box}body{margin:0;background:#f1f4f9;color:#25364d;font:15px "Microsoft YaHei",system-ui,sans-serif}main{max-width:1550px;margin:auto;padding:30px}.eyebrow{font-size:12px;letter-spacing:2px;font-weight:700;color:#178b79}h1{font-size:30px;margin:10px 0}p{line-height:1.8;color:#6a788b}.counts{display:flex;gap:12px;flex-wrap:wrap;margin:18px 0}.counts span{padding:8px 15px;background:#e0eee9;border-radius:20px;font-weight:700;font-size:13px;color:#12745e}.toolbar{display:flex;gap:10px;align-items:center;flex-wrap:wrap;background:white;border-radius:12px;padding:18px;margin:20px 0}button,select{font:inherit;font-size:13px;border:1px solid #d4dde8;background:white;color:#30445c;padding:10px 13px;border-radius:8px;cursor:pointer}button.primary{background:#178b79;color:white;border-color:#178b79}select:disabled{opacity:.45}input[type=range]{flex:1;min-width:170px;accent-color:#178b79}label{font-size:13px}#clock{min-width:85px;font-size:19px;font-weight:700;font-variant-numeric:tabular-nums}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.grid.overview{grid-template-columns:repeat(3,minmax(0,1fr))}.card{background:white;border:1px solid #dfe6ef;border-radius:12px;overflow:hidden}.head{padding:16px 17px 9px;display:flex;justify-content:space-between;gap:10px;align-items:start}.head strong{font-size:15px}.sub{font-size:11px;color:#778599;margin-top:5px}.chip{font-size:10px;padding:5px 7px;border-radius:6px;background:#edf1f7;white-space:nowrap}.good{background:#ddf2e9;color:#16765e}.bad{background:#fce6e1;color:#a84032}.warn{background:#fff0d0;color:#956514}canvas{width:100%;display:block}.stats{border-top:1px solid #edf1f6;padding:12px 17px 16px;display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.stats span{display:block;font-size:10px;color:#78889c;margin-bottom:6px}.stats b{font-size:14px}.note{padding:15px 20px;background:#e6edf7;border-radius:12px;font-size:13px;line-height:1.8;margin-top:20px}.links{display:flex;flex-wrap:wrap;gap:20px;margin:22px 0;font-size:13px}a{color:#178b79;text-decoration:none}@media(max-width:1100px){.grid.overview{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:750px){main{padding:20px 14px}.grid,.grid.overview{grid-template-columns:1fr}h1{font-size:24px}}
</style></head><body><main><div class="eyebrow">WEEK 06 / SIX MIXED AGENT SCENARIOS</div><h1>圆周交会：从 1 人 1 车到 6 人 6 车</h1><p>六组都使用半径 10 米的圆周对径布局与相同参数。查看六组同步总览，或选择任意一组比较四种交互模型。车辆按自己的初始直径方向运动，车车冲突也计入失败。</p>
<div class="counts"><span id="composition">场景二：六组总览</span><span>P 为行人 · C 为车辆 · 同编号为对径配对</span></div>
<div class="toolbar"><select id="family" aria-label="实验场景"><option value="circle">场景二 · 六组圆周交会</option><option value="narrow">场景一 · 4人1车窄路</option></select><select id="view" aria-label="查看方式"><option value="overview">六组总览</option><option value="models">单组四模型</option></select><select id="setting" aria-label="数量或路宽"></select><button id="play" class="primary">播放</button><button id="reset">重置</button><input id="timeline" aria-label="时间轴" type="range" min="0" max="40" step="0.1" value="0"><span id="clock">0.0 s</span><select id="rate" aria-label="播放速度"><option value="0.5">0.5×</option><option value="1" selected>1×</option><option value="2">2×</option><option value="4">4×</option></select><label><input id="zoom" type="checkbox">局部放大</label></div>
<div class="grid overview" id="grid"></div><div class="note" id="note"></div><div class="note">GOAL：无主体避让基线 · DIST：距离排斥 · PRED：预测排斥 · SIDE：预测排斥＋右侧偏好。<br>净空/分离裕度小于 0 表示重叠。车车 SAT 裕度用于分离判断，不是精确欧氏距离。重叠后的轨迹仅作诊断，后续到达不能记为安全成功。</div>
<div class="links"><a href="summary.png">六组一页总览 ↗</a><a href="circle_models.png">全部24项模型对照 ↗</a><a href="circle_layouts.png">六组初始布局 ↗</a><a href="circle_safety.png">三类冲突热图 ↗</a><a href="circle_dynamics.png">数量与指标变化 ↗</a><a href="narrow_comparison.png">保留的窄路实验 ↗</a><a href="experiment_metrics.csv">全部指标CSV ↗</a></div>
</main><script>
const D=__DATA__, models=['GOAL','DIST','PRED','SIDE'];
const titles={GOAL:'目标驱动',DIST:'距离排斥',PRED:'预测排斥',SIDE:'预测＋绕行偏好'};
const states={success:'完成且无重叠',collision:'发生重叠',boundary:'发生越界',timeout:'时限内未完成'};
const pedColors=['#178b79','#2f9fb0','#557bc1','#9274b3','#1c6f91','#79a641'];
const carColors=['#d35a56','#bd4c65','#dd7c42','#ae4138','#b9628c','#c88835'];
const $=id=>document.getElementById(id);let current=0,playing=false,last=null,cards=[];
const fmt=(v,n=3)=>v===null||v===undefined?'—':Number(v).toFixed(n);
function selectFamily(){const road=$('family').value==='narrow';$('view').disabled=road;$('setting').innerHTML=(road?[3.5,3.,2.8,2.4]:[1,2,3,4,5,6]).map(v=>`<option value="${road?v.toFixed(1):v}">${road?'路宽 '+v.toFixed(1)+' m':v+' 人＋'+v+' 车'}</option>`).join('');setup()}
function setup(){playing=false;current=0;last=null;$('play').textContent='播放';$('timeline').value=0;
const road=$('family').value==='narrow',overview=!road&&$('view').value==='overview';$('setting').disabled=overview;
const choice=$('setting').value;let keys=road?models.map(m=>`narrow_${choice}_${m}`):overview?[1,2,3,4,5,6].map(n=>`circle_n${n}_SIDE`):models.map(m=>`circle_n${choice}_${m}`);
$('grid').className=overview?'grid overview':'grid';$('composition').textContent=road?'场景一：4 个行人＋1 辆车':overview?'场景二六组总览：1人1车 → 6人6车':`场景二第${choice}组：${choice} 人＋${choice} 车，共 ${2*choice} 个主体`;
$('note').textContent=road?'窄路保留4个独立行人与1辆车，汽车沿道路中心线前进，所有模型参数与上一版一致。':'所有2N个起点在同一个10米圆周上均匀分布：车辆在右半圆，配对行人在对径的左半圆。每个人和车都朝自己的对径目标运动；大虚线圆只是起点布局，没有实体圆形墙。';
$('grid').innerHTML='';cards=keys.map(key=>{const d=D[key],m=d.metric,div=document.createElement('section');div.className='card';div.innerHTML=`<div class="head"><div><strong>${overview?m.pedestrians+' 人＋'+m.cars+' 车 · SIDE':m.model+' / '+titles[m.model]}</strong><div class="sub">${m.pedestrians} 个行人＋${m.cars} 辆车 · 全程指标</div></div><span class="chip ${m.status==='success'?'good':m.status==='timeout'?'warn':'bad'}">${states[m.status]}</span></div><canvas width="1000" height="${road?390:930}"></canvas><div class="stats"><div><span>人车最小净空</span><b>${fmt(m.min_car_clearance_m)} m</b></div><div><span>${road?'人际最小净空':'车车SAT裕度'}</span><b>${fmt(road?m.min_pedestrian_clearance_m:m.min_vehicle_clearance_m)} m</b></div><div><span>行人 / 车辆到达</span><b>${fmt(m.pedestrian_arrival_fraction*100,0)}% / ${fmt(m.car_arrival_fraction*100,0)}%</b></div></div>`;$('grid').append(div);return{d,canvas:div.querySelector('canvas')};});draw()}
function draw(){const road=$('family').value==='narrow',width=road?+$('setting').value:null;$('timeline').value=current;$('clock').textContent=current.toFixed(1)+' s';
for(const {d,canvas} of cards){const c=canvas.getContext('2d'),w=canvas.width,h=canvas.height,idx=Math.min(d.time.length-1,Math.floor(current/.1+1e-5)),x=d.position[idx];
let bounds=road?($('zoom').checked?[8,26,-3.5,3.5]:[0,40,-7,7]):($('zoom').checked?[-6.5,6.5,-6.5,6.5]:[-12.8,12.8,-12.8,12.8]);
let scale=Math.min((w-60)/(bounds[1]-bounds[0]),(h-80)/(bounds[3]-bounds[2]));let cx=w/2-(bounds[0]+bounds[1])/2*scale,cy=h/2+(bounds[2]+bounds[3])/2*scale;const X=v=>cx+v*scale,Y=v=>cy-v*scale;c.clearRect(0,0,w,h);c.save();c.beginPath();c.rect(20,20,w-40,h-65);c.clip();
if(road){c.fillStyle='#e9eef4';c.fillRect(X(0),Y(width/2),40*scale,width*scale);c.strokeStyle='#8090a6';c.lineWidth=2;for(const s of [-1,1]){c.beginPath();c.moveTo(X(0),Y(s*width/2));c.lineTo(X(40),Y(s*width/2));c.stroke()}}else{c.strokeStyle='#b8c4d3';c.setLineDash([9,9]);c.beginPath();c.arc(X(0),Y(0),10*scale,0,2*Math.PI);c.stroke();c.setLineDash([])}
const failed=(d.metric.collision_time_s!==null&&current>=d.metric.collision_time_s)||(d.metric.boundary_time_s!==null&&current>=d.metric.boundary_time_s);let pi=0,ci=0;
for(let j=0;j<x.length;j++){const car=d.half_box[j][0]>0,rank=car?ci++:pi++,color=(car?carColors:pedColors)[rank%6],p=x[j];c.beginPath();const lo=Math.max(0,idx-70);for(let k=lo;k<=idx;k++){const q=d.position[k][j];if(k===lo)c.moveTo(X(q[0]),Y(q[1]));else c.lineTo(X(q[0]),Y(q[1]))}c.strokeStyle=color+'77';c.lineWidth=2;c.stroke();c.fillStyle=color;c.strokeStyle=failed?'#ac352e':car?'#8f302d':'#254452';c.lineWidth=failed?3:1.5;
if(car){const theta=Math.atan2(d.heading[j][1],d.heading[j][0]);c.save();c.translate(X(p[0]),Y(p[1]));c.rotate(-theta);c.beginPath();c.rect(-2.2*scale,-.9*scale,4.4*scale,1.8*scale);c.fill();c.stroke();c.fillStyle='#ffe5d8';c.fillRect(1.25*scale,-.65*scale,.45*scale,1.3*scale);c.restore();c.fillStyle='white';c.textAlign='center';c.font='bold 20px Microsoft YaHei';c.fillText('C'+(rank+1),X(p[0]),Y(p[1])+7)}else{c.beginPath();c.arc(X(p[0]),Y(p[1]),.25*scale,0,2*Math.PI);c.fill();c.stroke();c.fillStyle='#354a63';c.textAlign='center';c.font='19px Microsoft YaHei';c.fillText('P'+(rank+1),X(p[0]),Y(p[1])+.7*scale)}}
c.restore();c.fillStyle=failed?'#b33d30':'#718198';c.textAlign='left';c.font='18px Microsoft YaHei';c.fillText(failed?'已发生失败 · 后续仅作诊断':`${d.metric.pedestrians} 个行人＋${d.metric.cars} 辆车 · 车身朝向按实际航向绘制`,25,h-18)}}
function frame(stamp){if(playing){if(last!==null)current=Math.min(40,current+(stamp-last)/1000*+$('rate').value);if(current>=40){playing=false;$('play').textContent='播放'}draw()}last=stamp;requestAnimationFrame(frame)}
$('family').onchange=selectFamily;$('setting').onchange=setup;$('view').onchange=setup;$('zoom').onchange=draw;$('timeline').oninput=()=>{current=+$('timeline').value;draw()};$('play').onclick=()=>{if(current>=40)current=0;playing=!playing;last=null;$('play').textContent=playing?'暂停':'播放'};$('reset').onclick=()=>{playing=false;current=0;$('play').textContent='播放';draw()};selectFamily();requestAnimationFrame(frame);
</script></body></html>'''
    (out/'replay.html').write_text(html.replace('__DATA__',json.dumps(data,separators=(',',':'),ensure_ascii=False)),encoding='utf8')
